use vstd::prelude::*;

verus! {
    // Append two Vec<f32>’s, preserving order.
    // Guarantees:
    //   result.len() == arr.len() + values.len()
    //   ∀i < arr.len(): result[i] == arr[i]
    //   ∀j < values.len(): result[arr.len() + j] == values[j]
    fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (res: Vec<f32>)
        ensures
            res.len() == arr.len() + values.len(),
            forall(|i: usize| i < arr.len() ==> res.index(i) == arr.index(i)),
            forall(|j: usize| j < values.len() ==> res.index(arr.len() + j) == values.index(j)),
    {
        // Pre-allocate the final size for efficiency.
        let mut res: Vec<f32> = Vec::with_capacity(arr.len() + values.len());

        // First loop: copy arr[0..arr.len()] into res[0..arr.len()].
        let mut i: usize = 0;
        while i < arr.len()
            invariant
                // i runs from 0 up to arr.len()
                i <= arr.len(),
                // so far we have pushed exactly i elements
                res.len() == i,
                // and those i elements match arr[0..i]
                forall(|k: usize| k < i ==> res.index(k) == arr.index(k))
            decreases arr.len() - i,
        {
            res.push(arr.index(i));
            i = i + 1;
        }

        // At this point: res.len() == arr.len(), and ∀k < arr.len() res[k] == arr[k].

        // Second loop: copy values[0..values.len()] into res[arr.len() .. arr.len()+values.len()].
        let mut j: usize = 0;
        while j < values.len()
            invariant
                j <= values.len(),
                // we've now pushed arr.len()+j elements total
                res.len() == arr.len() + j,
                // the tail we just built matches values[0..j]
                forall(|k: usize| k < j
                    ==> res.index(arr.len() + k) == values.index(k)),
                // and the prefix still matches arr
                forall(|k: usize| k < arr.len()
                    ==> res.index(k) == arr.index(k))
            decreases values.len() - j,
        {
            res.push(values.index(j));
            j = j + 1;
        }

        // Finally res.len() == arr.len() + values.len(), with all elements in place.
        res
    }
}

